const item = $input.first().json;
// The @n8n/n8n-nodes-langchain.googleGemini node returns:
// { content: { parts: [ { text, thought? }, ... ] } }
// Concatenate only the non-thought parts to recover the model's answer.
let raw = '';
if (item.text) {
  raw = item.text;
} else if (item.content && Array.isArray(item.content.parts)) {
  raw = item.content.parts
    .filter(p => !p.thought)
    .map(p => p.text || '')
    .join('');
} else if (typeof item === 'string') {
  raw = item;
}

function extractJson(s) {
  let m = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (m) s = m[1];
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a !== -1 && b !== -1 && b > a) s = s.slice(a, b + 1);
  return s;
}

let parsed;
try {
  parsed = JSON.parse(extractJson(raw));
} catch (e) {
  parsed = { summary: 'Extraction fallback: could not parse model JSON.', actionItems: [], keyDecisions: [] };
}

parsed.summary = parsed.summary || '';
parsed.actionItems = Array.isArray(parsed.actionItems) ? parsed.actionItems : [];
parsed.keyDecisions = Array.isArray(parsed.keyDecisions) ? parsed.keyDecisions : [];

return [{
  json: {
    summary: parsed.summary,
    actionItems: parsed.actionItems,
    keyDecisions: parsed.keyDecisions
  }
}];

const d = $input.first().json;
const title = $('Prepare Transcript').item.json.meetingTitle;
const date = $('Prepare Transcript').item.json.meetingDate;
const actionLines = (d.actionItems || []).map((a, i) =>
  `${i + 1}. ${a.task || 'Task'} — Owner: ${a.owner || 'TBD'}, Due: ${a.dueDate || 'TBD'}`).join('\n');
const decisionLines = (d.keyDecisions || []).map((x, i) => `${i + 1}. ${x}`).join('\n');
const slackActionLines = (d.actionItems || []).map(a =>
  `• ${a.task || 'Task'} — ${a.owner || 'TBD'} (due ${a.dueDate || 'TBD'})`).join('\n');
const slackDecisionLines = (d.keyDecisions || []).map(x => `• ${x}`).join('\n');
const slackMessage =
  `:memo: *Meeting Recap — ${title} (${date})*\n\n` +
  `*Summary:* ${d.summary}\n\n` +
  `*Action Items:*\n${slackActionLines || '• None'}\n\n` +
  `*Key Decisions:*\n${slackDecisionLines || '• None'}`;
return [{ json: {
  title: `${title} — ${date}`,
  summary: d.summary,
  actionLines: actionLines || 'None',
  decisionLines: decisionLines || 'None',
  slackMessage,
  actionItemCount: (d.actionItems || []).length,
  decisionCount: (d.keyDecisions || []).length
}}];
